import json
import subprocess
import boto3
import os

def lambda_handler(event, context):
    """
    Step Functions task handler that processes data transformation requests.
    Receives input from a Step Functions state machine that orchestrates
    ETL pipeline stages.
    """

    # Extract parameters from Step Functions input
    transform_config = event.get('transformConfig', {})
    source_bucket = transform_config.get('sourceBucket', '')
    output_format = transform_config.get('outputFormat', 'csv')
    custom_delimiter = transform_config.get('delimiter', ',')

    # Validate basic parameters
    if not source_bucket:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'sourceBucket is required'})
        }

    # Build the transformation command using csvkit
    # The delimiter parameter is passed to csvformat for output formatting
    base_cmd = f"csvformat -D '{custom_delimiter}' /tmp/input_data.csv"

    # Additional processing flags based on output format
    if output_format == 'tsv':
        base_cmd = "csvformat -T /tmp/input_data.csv"
    elif output_format == 'custom':
        # User-specified delimiter for custom formats
        base_cmd = f"csvformat -D '{custom_delimiter}' /tmp/input_data.csv"

    # Download source file from S3
    s3_client = boto3.client('s3')
    source_key = transform_config.get('sourceKey', 'data/input.csv')

    try:
        s3_client.download_file(source_bucket, source_key, '/tmp/input_data.csv')
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': f'Failed to download: {str(e)}'})
        }

    # Execute transformation
    try:
        result = subprocess.run(
            base_cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=30
        )

        if result.returncode != 0:
            return {
                'statusCode': 500,
                'body': json.dumps({'error': result.stderr})
            }

        # Write output to S3
        output_key = transform_config.get('outputKey', 'data/output.csv')
        output_bucket = transform_config.get('outputBucket', source_bucket)

        with open('/tmp/output_data.csv', 'w') as f:
            f.write(result.stdout)

        s3_client.upload_file('/tmp/output_data.csv', output_bucket, output_key)

        return {
            'statusCode': 200,
            'body': json.dumps({
                'message': 'Transform complete',
                'outputBucket': output_bucket,
                'outputKey': output_key,
                'rowsProcessed': len(result.stdout.splitlines())
            })
        }

    except subprocess.TimeoutExpired:
        return {
            'statusCode': 504,
            'body': json.dumps({'error': 'Transform timed out'})
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': str(e)})
        }


def validate_state_machine_input(event):
    """Validates the structure of Step Functions input."""
    required_fields = ['transformConfig']
    for field in required_fields:
        if field not in event:
            raise ValueError(f'Missing required field: {field}')

    config = event['transformConfig']
    allowed_formats = ['csv', 'tsv', 'custom', 'json']
    if config.get('outputFormat', 'csv') not in allowed_formats:
        raise ValueError(f'Invalid outputFormat')

    return True
